    /// <summary>Returns the texture path for the particular tintMask type and index</summary>
    public static Task<string> GetTintMaskTexturePath(int type, int index) => Dispatcher.CallAsync<string>("GetTintMaskTexturePath", new PapyrusArguments().Add(type).Add(index))!;

    /// <summary>Sets the tintMask texture for the particular type and index</summary>
    public static Task SetTintMaskTexturePath(string path, int type, int index) => Dispatcher.CallAsync("SetTintMaskTexturePath", new PapyrusArguments().Add(path).Add(type).Add(index));

    /// <summary>Updates tintMask colors without updating the entire model</summary>
    public static Task UpdateTintMaskColors() => Dispatcher.CallAsync("UpdateTintMaskColors");

    /// <summary>Updates the players hair color immediately</summary>
    public static Task UpdateHairColor() => Dispatcher.CallAsync("UpdateHairColor");

    /// <summary>
    /// Returns the character's current camera state
    /// 0 - first person
    /// 1 - auto vanity
    /// 2 - VATS
    /// 3 - free
    /// 4 - iron sights
    /// 5 - furniture
    /// 6 - transition
    /// 7 - tweenmenu
    /// 8 - third person 1
    /// 9 - third person 2
    /// 10 - horse
    /// 11 - bleedout
    /// 12 - dragon
    /// </summary>
    public static Task<int> GetCameraState() => Dispatcher.CallAsync<int>("GetCameraState");

    /// <summary>
    /// set a misc stat value
    /// use QueryStat to read the value
    /// </summary>
    public static Task SetMiscStat(string name, int value) => Dispatcher.CallAsync("SetMiscStat", new PapyrusArguments().Add(name).Add(value));

    /// <summary>Sets the players last ridden horse, None will clear the lastRiddenHorse</summary>
    public static Task SetPlayersLastRiddenHorse(IActor horse) => Dispatcher.CallAsync("SetPlayersLastRiddenHorse", new PapyrusArguments().Add(horse));

    /// <summary>
    /// Returns the legendary level for the skill
    /// -1 indicates the particular skill cannot have a legendary level
    /// DEPRECATED
    /// </summary>
    [Obsolete("Game.psc deprecates GetSkillLegendaryLevel.", DiagnosticId = "SF0003")]
    public static Task<int> GetSkillLegendaryLevel(string actorValue) => Dispatcher.CallAsync<int>("GetSkillLegendaryLevel", new PapyrusArguments().Add(actorValue));

    /// <summary>
    /// Sets the legendary level for the skill
    /// DEPRECATED
    /// </summary>
    [Obsolete("Game.psc deprecates SetSkillLegendaryLevel.", DiagnosticId = "SF0003")]
    public static Task SetSkillLegendaryLevel(string actorValue, int level) => Dispatcher.CallAsync("SetSkillLegendaryLevel", new PapyrusArguments().Add(actorValue).Add(level));

    /// <summary>Returns the players experience for this level (not total experience)</summary>
    public static Task<float> GetPlayerExperience() => Dispatcher.CallAsync<float>("GetPlayerExperience");

    /// <summary>Sets the players experience, does not trigger level-up notification</summary>
    public static Task SetPlayerExperience(float exp) => Dispatcher.CallAsync("SetPlayerExperience", new PapyrusArguments().Add(exp));

    /// <summary>
    /// Calculates the experience required for to level-up
    /// (fXPLevelUpBase + currentLevel * fXPLevelUpMult)
    /// </summary>
    public static Task<float> GetExperienceForLevel(int currentLevel) => Dispatcher.CallAsync<float>("GetExperienceForLevel", new PapyrusArguments().Add(currentLevel));

    /// <summary>
    /// Returns true if in run mode, false if in walk mode
    /// Does not reflect actual movement state, only the control mode
    /// </summary>
    public static Task<bool> GetPlayerMovementMode() => Dispatcher.CallAsync<bool>("GetPlayerMovementMode");

    /// <summary>Updates the camera when changing Shoulder positions</summary>
    [Obsolete("Uses the Papyrus virtual machine. Prefer PlayerCamera.UpdateThirdPerson(bool).", DiagnosticId = "SF0004")]
    public static Task UpdateThirdPerson() => Dispatcher.CallAsync("UpdateThirdPerson");

    /// <summary>
    /// Hotkeys 0-7 reflect keys 1-8
    /// Unbinds a favorited item bound to the specified hotkey
    /// </summary>
    public static Task UnbindObjectHotkey(int hotkey) => Dispatcher.CallAsync("UnbindObjectHotkey", new PapyrusArguments().Add(hotkey));

    /// <summary>Returns the base form object that is bound to the specified hotkey</summary>
    public static Task<Form?> GetHotkeyBoundObject(int hotkey) => Dispatcher.CallAsync<Form?>("GetHotkeyBoundObject", new PapyrusArguments().Add(hotkey));

    /// <summary>Returns if base form is favorited by the player</summary>
    public static Task<bool> IsObjectFavorited(IForm form) => Dispatcher.CallAsync<bool>("IsObjectFavorited", new PapyrusArguments().Add(form));

    /// <summary>Same as GetForm, but also works for formIds &gt;= 0x80000000</summary>
    public static Task<Form?> GetFormEx(int formId) => Dispatcher.CallAsync<Form?>("GetFormEx", new PapyrusArguments().Add(formId));

    /// <summary>Returns the object reference the player is in dialogue with</summary>
    public static Task<ObjectReference?> GetDialogueTarget() => Dispatcher.CallAsync<ObjectReference?>("GetDialogueTarget");

    /// <summary>Returns the current crosshair ref</summary>
    public static Task<ObjectReference?> GetCurrentCrosshairRef() => Dispatcher.CallAsync<ObjectReference?>("GetCurrentCrosshairRef");

    /// <summary>Returns the currently selected ref in the console</summary>
    public static Task<ObjectReference?> GetCurrentConsoleRef() => Dispatcher.CallAsync<ObjectReference?>("GetCurrentConsoleRef");

    /// <summary>Sets the player level</summary>
    public static Task SetPlayerLevel(int level) => Dispatcher.CallAsync("SetPlayerLevel", new PapyrusArguments().Add(level));
